    if simulation._formulation == "EB":
        MfMui = simulation.mesh.get_face_inner_product(1.0 / self.mu)

        if (
            self.waveform.has_initial_fields is True
            and time < simulation.time_steps[1]
        ):
            return C.T * (MfMui * b)
        else:
